package ai.decisionos.aside;
import android.content.*;import android.os.Bundle;import org.json.*;
/** Live OS alarm -> persisted state -> authenticated portal read -> home, no writes to external services. */
final class ScheduledWorkChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();try{Context c=i.getTargetContext();String phase=i.scenario.getString("scheduledPhase","verify");android.content.SharedPreferences p=c.getSharedPreferences("scheduled_work_test",0);
 if(phase.equals("notification")){String id;long now=System.currentTimeMillis();try(ScheduledWorkStore s=new ScheduledWorkStore(c)){id=s.create(p.getString("goal",""),"REGRESSION_SCHEDULED_NOTIFICATION_0620","기한 알림 확인","reminder","",now+5000,now);}p.edit().putString("notification",id).commit();ScheduledWork.arm(c,id);for(int n=0;n<60;n++){Thread.sleep(1000);try(ScheduledWorkStore s=new ScheduledWorkStore(c)){if(s.get(id).optInt("dispatch_count")==1)break;}}try(ScheduledWorkStore s=new ScheduledWorkStore(c)){i.check(s.get(id).optString("notification").equals("posted"),"real notification posted");}boolean found=false;for(android.service.notification.StatusBarNotification n:c.getSystemService(android.app.NotificationManager.class).getActiveNotifications())if(id.equals(n.getTag()))found=true;i.check(found,"notification present in system manager");out.putString("stream","PASS "+i.checks+" actual notification posting checks\n");}
 else if(phase.equals("location")){android.location.Location l=new android.location.Location("synthetic");l.setLatitude(35.57);l.setLongitude(129.19);l.setAccuracy(10);long now=android.os.SystemClock.elapsedRealtimeNanos();l.setElapsedRealtimeNanos(now);i.check(TravelLocation.usable(l,now),"fresh coordinates accepted");i.check(!TravelLocation.usable(l,now+121000000000L),"stale coordinates blocked");l.setAccuracy(500);i.check(!TravelLocation.usable(l,now),"inaccurate coordinates blocked");i.check(!TravelLocation.usable(null,now),"missing coordinates blocked");out.putString("stream","PASS "+i.checks+" location boundary checks (synthetic, not live GPS)\n");}
 else if(phase.equals("cleanup")){for(String key:new String[]{"id","cancelled","notification"}){String id=p.getString(key,"");if(!id.isEmpty()){ScheduledWork.cancel(c,id);try(ScheduledWorkStore s=new ScheduledWorkStore(c)){JSONObject row=s.get(id);try(CampusFlowStore events=new CampusFlowStore(c)){events.remove(SchoolChatWork.eventId("portal",id,row.optString("title")));}s.getWritableDatabase().delete("work","id=? AND title LIKE 'REGRESSION_SCHEDULED_%'",new String[]{id});}}}p.edit().clear().commit();out.putString("stream","PASS scheduled fixture cleanup\n");}
 else if(phase.equals("create")){String goal="";try(GoalStore s=new GoalStore(c)){for(JSONObject g:s.goals())if(!GoalStore.fixture(g)&&g.optString("character").equals("grades")){goal=g.optString("id");break;}}if(goal.isEmpty())throw new AssertionError("Existing school goal required");long now=System.currentTimeMillis();try(ScheduledWorkStore s=new ScheduledWorkStore(c)){String id=s.create(goal,"REGRESSION_SCHEDULED_PORTAL_0620","학교 공지를 실제 조회해 줘","portal_refresh","",now+20000,now);i.check(!s.claim(id,now),"never dispatch before due");String cancelled=s.create(goal,"REGRESSION_SCHEDULED_CANCEL_0620","취소 확인","reminder","",now+22000,now);ScheduledWork.arm(c,id);ScheduledWork.arm(c,cancelled);ScheduledWork.cancel(c,cancelled);i.check(s.get(cancelled).optString("state").equals("CANCELLED"),"cancel persisted");i.check(!s.claim(cancelled,now+30000),"cancel cannot dispatch");for(String url:new String[]{"https://zoom.us.evil.test/j/123","http://zoom.us/j/123","https://user:pw@zoom.us/j/123","https://zoom.us:444/j/123"})i.check(!ScheduledWork.zoomUrl(url),"meeting URL scope");i.check(ScheduledWork.zoomUrl("https://us02web.zoom.us/j/123456789"),"meeting HTTPS recognized");p.edit().putString("id",id).putString("goal",goal).putString("cancelled",cancelled).putLong("created",now).commit();out.putString("stream","PASS "+i.checks+" scheduled creation, boundaries; alarm waits independently of instrumentation process\n");}}
 else {String id=p.getString("id","");if(id.isEmpty())throw new AssertionError("Create phase required");JSONObject row=null;for(int n=0;n<180;n++){try(ScheduledWorkStore s=new ScheduledWorkStore(c)){row=s.get(id);}if(row.optString("state").equals("RESULT_READY")||row.optString("state").equals("FAILED"))break;Thread.sleep(1000);}if(row==null)throw new AssertionError("No work");i.check(row.optLong("fired_at")>=row.optLong("due_at"),"OS alarm fired after requested time");i.check(row.optInt("dispatch_count")==1,"one dispatch survives process death");ScheduledWork.fire(c,id);try(ScheduledWorkStore s=new ScheduledWorkStore(c)){i.check(s.get(id).optInt("dispatch_count")==1,"duplicate broadcast idempotency");i.check(s.get(p.getString("cancelled","")).optInt("dispatch_count")==0,"cancelled alarm never ran");}i.check(row.optString("state").equals("RESULT_READY"),"real portal response required: "+row.optString("detail"));i.check(c.getSharedPreferences(CampusNoticeMonitor.PREFS,0).getLong("last_checked",0)>=p.getLong("created",0),"new authenticated read timestamp");try(CampusFlowStore events=new CampusFlowStore(c)){i.check(events.get(SchoolChatWork.eventId("portal",id,row.optString("title"))).optString("text").equals(row.optString("detail")),"real result published into school chat");}GoalAgentActivity a=(GoalAgentActivity)i.startActivitySync(new Intent(c,GoalAgentActivity.class).putExtra("goal_id",p.getString("goal","")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));i.runOnMainSync(()->a.chat.companion.select("홈"));Thread.sleep(3000);java.util.concurrent.atomic.AtomicReference<String> dom=new java.util.concurrent.atomic.AtomicReference<>();i.runOnMainSync(()->a.chat.companion.tossHome.web.evaluateJavascript("document.body.innerText",dom::set));for(int n=0;n<30&&dom.get()==null;n++)Thread.sleep(100);i.check(dom.get()!=null&&dom.get().contains("REGRESSION_SCHEDULED_PORTAL_0620")&&dom.get().contains("실제 조회 결과 도착"),"live work visible in home DOM");android.graphics.Bitmap shot=i.getUiAutomation().takeScreenshot();try(java.io.OutputStream f=new java.io.FileOutputStream(new java.io.File(c.getCacheDir(),"scheduled-home.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}shot.recycle();out.putString("stream","PASS "+i.checks+" live alarm, process persistence, portal result and home DOM checks\n"+row.toString()+"\n");}
 }catch(Throwable e){out.putString("stream","FAIL "+e+"\n");}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
}
